data class Product(val id: String, val name: String, val price: Double)

interface ProductRepository {
    suspend fun getProducts(): List<Product>
}

// 1. Modela el estado: Loading, Success(lista) y Error(mensaje)
// 2. Expón un StateFlow de solo lectura
// 3. Carga los productos al crear el ViewModel
// 4. Si falla, pasa a Error con un mensaje

class ProductsViewModel(
    private val repository: ProductRepository
) : ViewModel() {

}

challenges.solution:
sealed interface ProductsUiState {
    data object Loading : ProductsUiState
    data class Success(val products: List<Product>) : ProductsUiState
    data class Error(val message: String) : ProductsUiState
}

class ProductsViewModel(
    private val repository: ProductRepository
) : ViewModel() {

    private val _uiState =
        MutableStateFlow<ProductsUiState>(ProductsUiState.Loading)
    val uiState: StateFlow<ProductsUiState> = _uiState.asStateFlow()

    init {
        load()
    }

    fun load() {
        viewModelScope.launch {
            _uiState.value = ProductsUiState.Loading
            _uiState.value = try {
                ProductsUiState.Success(repository.getProducts())
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                ProductsUiState.Error(e.message ?: "Error desconocido")
            }
        }
    }
}

