// Requisitos:
// - El TextField escribe el texto en el ViewModel
// - Espera 300 ms sin escribir antes de buscar
// - No repitas la búsqueda si el texto no cambió
// - Si llega un texto nuevo, cancela la búsqueda en curso
// - Texto vacío = lista vacía, sin llamar al repositorio
// - Un error no debe romper el flujo
// - Expón los resultados como StateFlow

class SearchViewModel(
    private val repository: SearchRepository
) : ViewModel() {

}

challenges.solution:
@OptIn(FlowPreview::class, ExperimentalCoroutinesApi::class)
class SearchViewModel(
    private val repository: SearchRepository
) : ViewModel() {

    private val _query = MutableStateFlow("")
    val query: StateFlow<String> = _query.asStateFlow()

    val results: StateFlow<List<String>> = _query
        .debounce(300)
        .map { it.trim() }
        .distinctUntilChanged()
        .mapLatest { q ->
            if (q.isBlank()) emptyList()
            else try {
                repository.search(q)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                emptyList()
            }
        }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5_000),
            initialValue = emptyList()
        )

    fun onQueryChange(value: String) {
        _query.value = value
    }
}

