data class Article(val id: String, val title: String, val body: String)

// Implementa un repositorio offline-first:
// - La UI observa SIEMPRE la base de datos local
// - refresh() trae datos de red y los guarda en la base de datos
// - refresh() devuelve Result<Unit> y no rompe la cancelación
// - Convierte entidades y DTOs a modelos (Article)

class ArticleRepository(
    private val api: ArticleApi,
    private val dao: ArticleDao
) {

}

challenges.solution:
class ArticleRepository(
    private val api: ArticleApi,
    private val dao: ArticleDao
) {
    fun observeArticles(): Flow<List<Article>> =
        dao.observeAll().map { entities -> entities.map { it.toDomain() } }

    suspend fun refresh(): Result<Unit> =
        try {
            val remote = api.fetchArticles()
            dao.upsertAll(remote.map { it.toEntity() })
            Result.success(Unit)
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            Result.failure(e)
        }
}

private fun ArticleEntity.toDomain() =
    Article(id = id, title = title, body = body)

private fun ArticleDto.toEntity() =
    ArticleEntity(id = id, title = title, body = body)

