class TokenManager(private val api: AuthApi) {
    private val mutex = Mutex()

    var currentToken: String? = null
        private set

    suspend fun refreshIfNeeded(staleToken: String?): String =
        mutex.withLock {
            val token = currentToken
            // Otra corrutina ya lo renovó mientras esperábamos el lock
            if (token != null && token != staleToken) return@withLock token

            api.refreshToken().also { currentToken = it }
        }
}

