// Implementa retryWithBackoff:
// - Ejecuta block hasta `times` veces en total
// - Espera initialDelay, luego initialDelay * factor, etc. (máx. maxDelay)
// - Si todos los intentos fallan, lanza la última excepción
// - Nunca reintentes una cancelación

suspend fun <T> retryWithBackoff(
    times: Int = 3,
    initialDelay: Long = 500,
    maxDelay: Long = 5_000,
    factor: Double = 2.0,
    block: suspend () -> T
): T {
    TODO()
}

challenges.solution:
suspend fun <T> retryWithBackoff(
    times: Int = 3,
    initialDelay: Long = 500,
    maxDelay: Long = 5_000,
    factor: Double = 2.0,
    block: suspend () -> T
): T {
    require(times > 0) { "times debe ser mayor que 0" }
    var currentDelay = initialDelay
    repeat(times - 1) {
        try {
            return block()
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            // Falla: se espera y se reintenta
        }
        delay(currentDelay)
        currentDelay = (currentDelay * factor).toLong().coerceAtMost(maxDelay)
    }
    return block() // Último intento: si falla, la excepción sube
}
